 on our channel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/V2C0sMXyD80/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2021-02-19T17:00:11Z","viewCount":776251,"durationSeconds":2546,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
